-- BUGÜN: Aksaray'ın temel kültür ve doğa rotası.
insert into public.places
  (name, category, place_type, city, address, latitude, longitude, slug,
   short_description, long_description, source_url, external_source, external_id,
   verified, trust_score, is_active, content_review_status, tags)
select v.name, v.category, v.place_type, 'Aksaray', v.address, v.lat, v.lon, v.slug,
       v.short_description, v.long_description, v.source_url, 'curated_seed',
       'aksaray-' || v.slug, false, 80, true, 'source_backed', v.tags::jsonb
from (values
 ('Ihlara Vadisi','Doğa','Kanyon ve ören yeri','Güzelyurt, Aksaray',38.2500::float8,34.3000::float8,'ihlara-vadisi','Melendiz Çayı boyunca uzanan kanyon, kaya kiliseleri ve yürüyüş güzergâhları.','Yaklaşık 14 kilometrelik vadi, doğal peyzajı ve kaya oyma kiliseleriyle Aksaray’ın başlıca gezi noktasıdır.','https://kulturportali.gov.tr/turkiye/aksaray/gezilecekyer/ihlara-vadisi','["kanyon","doğa","tarih","yürüyüş"]'),
 ('Selime Katedrali ve Peribacaları','Tarih','Kaya manastırı ve kaya oluşumları','Selime, Güzelyurt, Aksaray',38.3000::float8,34.3000::float8,'selime-katedrali','Kaya içine oyulmuş büyük manastır yapısı ve çevresindeki oluşumlar.','Ihlara Vadisi’nin kuzey ucuna yakın Selime’de, kayaya oyulmuş dini yapılar ve Kapadokya peyzajı birlikte görülebilir.','https://aksaray.ktb.gov.tr/TR-395740/gorulmesi-gereken-yerler.html','["tarih","kaya mimarisi","Kapadokya"]'),
 ('Manastır Vadisi','Doğa','Kaya kiliseleri ve vadi','Güzelyurt, Aksaray',38.2800::float8,34.3700::float8,'manastir-vadisi','Kaya oyma kiliseler, şapeller ve yeraltı mekânlarıyla bilinen vadi.','Güzelyurt’taki koruma alanı, tarihî dini yapıları ve yürüyüş imkânlarını bir arada sunar; bazı yapılar ziyarete kapalı olabilir.','https://kulturportali.gov.tr/turkiye/aksaray/gezilecekyer/aksaray-manastir-vadisi','["vadi","kaya kiliseleri","tarih"]'),
 ('Aksaray Müzesi','Müze','Arkeoloji müzesi','Merkez, Aksaray',38.3700::float8,34.0300::float8,'aksaray-muzesi','Aksaray ve çevresinin arkeolojik geçmişini anlatan müze.','Bölgedeki tarih öncesi yerleşimler ve farklı uygarlıklara ait eserleri görmek için uygun başlangıç noktasıdır.','https://dosim.ktb.gov.tr/TR-321117/aksaray.html','["müze","arkeoloji","tarih"]'),
 ('Aşıklı Höyük','Tarih','Neolitik yerleşim','Gülağaç, Aksaray',38.3500::float8,34.2300::float8,'asikli-hoyuk','Anadolu’da yerleşik yaşama geçişi anlamak açısından önemli Neolitik yerleşim.','Kazı alanı, yaklaşık MÖ 9. binyıla uzanan yerleşim izleriyle erken köy yaşamını araştıranlar için önemli arkeolojik duraktır.','https://turkishmuseums.kprod.kultur.gov.tr/blog/detail/must-see-places-in-aksaray/10095/1','["arkeoloji","Neolitik","tarih"]'),
 ('Nora Antik Kenti','Tarih','Roma-Bizans yerleşimi','Helvadere, Merkez, Aksaray',38.1700::float8,34.1700::float8,'nora-antik-kenti','Hasan Dağı eteklerinde Roma ve Bizans dönemlerinden kalıntılar.','Helvadere çevresindeki antik yerleşim, Aksaray’ın tarihî ve arkeolojik gezi rotalarında yer alır.','https://aksaray.ktb.gov.tr/TR-243001/oren-yerleri.html','["antik kent","arkeoloji","Roma","Bizans"]'),
 ('Saratlı Kırkgöz Yeraltı Şehri','Tarih','Yeraltı şehri','Saratlı, Gülağaç, Aksaray',38.3500::float8,34.2500::float8,'saratli-kirkgoz-yeralti-sehri','Kapadokya bölgesinin yeraltı yerleşimlerinden biri.','Kayalara oyulmuş yeraltı mekânları bölgenin korunma ve yaşam kültürünü anlamak için ziyaret edilir; ziyaret saatleri önceden kontrol edilmelidir.','https://dosim.ktb.gov.tr/TR-321117/aksaray.html','["yeraltı şehri","tarih","Kapadokya"]'),
 ('Aziz Mercurius Yeraltı Şehri','Tarih','Yeraltı şehri','Gülağaç, Aksaray',38.3500::float8,34.2500::float8,'aziz-mercurius-yeralti-sehri','Aksaray çevresindeki tarihî yeraltı yerleşimlerinden.','Aksaray Müze Müdürlüğü sorumluluğundaki arkeolojik alanlar arasında anılır; açık olma durumu ziyaret öncesi teyit edilmelidir.','https://dosim.ktb.gov.tr/TR-321117/aksaray.html','["yeraltı şehri","arkeoloji","tarih"]'),
 ('Ağzıkarahan Kervansarayı','Tarih','Selçuklu kervansarayı','Merkez ilçesi çevresi, Aksaray',38.4000::float8,34.0500::float8,'agzikarahan-kervansarayi','Selçuklu dönemi kervansaray mimarisinin önemli örneği.','Anadolu Selçuklu ticaret yollarındaki konaklama yapılarından biri olarak tarihî mimari rotasında öne çıkar.','https://aksaray.ktb.gov.tr/TR-395739/aksaray-rotalari.html','["Selçuklu","kervansaray","mimari"]'),
 ('Somuncu Baba Türbesi ve Külliyesi','Kültür','Türbe ve külliye','Merkez, Aksaray',38.3700::float8,34.0300::float8,'somuncu-baba-turbesi-aksaray','Aksaray’ın bilinen kültürel ve manevi ziyaret noktalarından.','Şehir merkezindeki kültür rotasında ziyaret edilen türbe ve külliye alanıdır.','https://aksaray.ktb.gov.tr/TR-395739/aksaray-rotalari.html','["kültür","tarih","ziyaret"]'),
 ('Eğri Minare','Tarih','Tarihî minare','Merkez, Aksaray',38.3700::float8,34.0300::float8,'egri-minare','Eğimli görünümüyle tanınan tarihî tuğla minare.','Aksaray şehir merkezindeki Selçuklu dönemi mirasının tanınmış yapılarındandır.','https://aksaray.ktb.gov.tr/TR-395739/aksaray-rotalari.html','["mimari","Selçuklu","tarih"]'),
 ('Zinciriye Medresesi','Tarih','Medrese','Merkez, Aksaray',38.3700::float8,34.0300::float8,'zinciriye-medresesi','Aksaray’ın tarihî merkezindeki medrese yapısı.','Geleneksel eğitim yapısı, şehir merkezinde tarihî mimari gezisinin parçası olarak görülebilir.','https://aksaray.ktb.gov.tr/TR-395739/aksaray-rotalari.html','["medrese","mimari","tarih"]'),
 ('Hasan Dağı','Doğa','Volkanik dağ','Aksaray ve Niğde sınırı',38.1300::float8,34.1700::float8,'hasan-dagi','Bölgenin simge volkanik dağlarından; manzara ve dağcılık alanı.','Hasan Dağı çevresinde yürüyüş ve tırmanış faaliyetleri hava, mevsim, ekipman ve güvenlik koşullarına bağlıdır.','https://aksaray.ktb.gov.tr/TR-395739/aksaray-rotalari.html','["dağ","doğa","dağcılık"]'),
 ('Mamasın Baraj Gölü','Doğa','Baraj gölü','Merkez, Aksaray',38.4000::float8,34.1000::float8,'mamasin-baraj-golu','Aksaray çevresinde göl manzarası ve açık hava alanı.','Baraj gölü çevresi manzara ve doğa gezileri için değerlendirilebilir; kıyı erişimi ve güvenlik işaretlerine uyulmalıdır.','https://kulturportali.gov.tr/turkiye/aksaray/gezilecekyer/ihlara-vadisi','["göl","manzara","doğa"]'),
 ('Kilise Camii (Aziz Gregorius)','Tarih','Tarihî kilise-cami','Güzelyurt, Aksaray',38.2800::float8,34.3700::float8,'kilise-camii-aziz-gregorius','Güzelyurt’un çok katmanlı dinî tarihini yansıtan yapı.','Manastır Vadisi başlangıcındaki yapı, bölgenin Bizans ve sonraki dönem tarihini anlamak için önemli bir duraktır.','https://aksaray.ktb.gov.tr/TR-395740/gorulmesi-gereken-yerler.html','["mimari","dinî miras","tarih"]'),
 ('Yüksek Kilise','Tarih','Kaya kilisesi','Güzelyurt, Aksaray',38.2800::float8,34.3700::float8,'yuksek-kilise-aksaray','Güzelyurt çevresindeki tarihî kaya kilisesi.','Kapadokya’nın kaya oyma dini mimarisiyle ilişkili yapı, Aksaray’ın resmî gezi listelerinde yer alır.','https://aksaray.ktb.gov.tr/TR-395740/gorulmesi-gereken-yerler.html','["kilise","kaya mimarisi","tarih"]'),
 ('Sultanhanı Kervansarayı','Tarih','Selçuklu kervansarayı','Sultanhanı, Aksaray',38.2500::float8,33.5500::float8,'sultanhani-kervansarayi','Anadolu Selçuklu döneminin anıtsal kervansaraylarından.','İpek Yolu güzergâhındaki büyük kervansaray yapısı, Aksaray çevresinin en önemli tarihî mimari duraklarından biridir.','https://aksaray.ktb.gov.tr/','["Selçuklu","kervansaray","tarih"]')
) as v(name,category,place_type,address,lat,lon,slug,short_description,long_description,source_url,tags)
where not exists (
 select 1 from public.places p
 where lower(trim(p.city))='aksaray'
   and (lower(trim(p.name))=lower(trim(v.name)) or p.slug=trim(v.slug))
);